test('permanent deletion: owner-only, Trash-only, tombstoned against re-import, cleans unreferenced media', async t => {
  const s = await setup(t);
  const own = (await s.upload(png(70))).data.url, shared = (await s.upload(png(71))).data.url, carted = (await s.upload(png(72))).data.url;
  s.cartLine(carted);
  await s.patch(s.a, { photos: [own, shared, carted, s.supplierPhoto] }); await s.patch(s.b, { photos: [shared] });
  assert.equal((await s.call('owner', `/api/admin/products/${s.a.id}/permanent`, 'DELETE', { confirm: true })).status, 409, 'must be in Trash first');
  assert.equal((await s.call('owner', `/api/admin/products/${s.a.id}`, 'DELETE', { confirm: true })).status, 200);
  assert.equal((await s.call('manager', `/api/admin/products/${s.a.id}/permanent`, 'DELETE', { confirm: true })).status, 403, 'owner-only by default');
  assert.equal((await s.call('owner', `/api/admin/products/${s.a.id}/permanent`, 'DELETE', {})).status, 400, 'confirm required');
  const purged = await s.call('owner', `/api/admin/products/${s.a.id}/permanent`, 'DELETE', { confirm: true });
  assert.equal(purged.status, 200); assert.deepEqual(purged.data, { purged: true, mediaDeleted: 1 });
  assert.ok(!s.exists(own)); assert.ok(s.exists(shared), 'used by product B'); assert.ok(s.exists(carted), 'kept for the past cart');
  assert.equal(s.db.sqlite.prepare('SELECT COUNT(*) AS n FROM products WHERE id=?').get(s.a.id).n, 0);
  assert.equal(s.db.sqlite.prepare('SELECT COUNT(*) AS n FROM cart_lines').get().n, 1, 'cart snapshots untouched');
  assert.equal(s.db.sqlite.prepare("SELECT COUNT(*) AS n FROM audit_events WHERE action='product.purge'").get().n, 1);
  assert.equal((await s.call('owner', `/api/admin/suppliers/${s.supplier.id}/import`, 'POST', { items: [source('one'), source('two')] })).status, 200);
  assert.equal(s.db.sqlite.prepare("SELECT COUNT(*) AS n FROM products WHERE external_id='one'").get().n, 0, 'tombstone blocks re-import');
  assert.equal((await s.call('owner', `/api/admin/products/${s.b.id}/permanent`, 'DELETE', { confirm: true })).status, 409, 'B is not in Trash');
});

test('media library: flags, permission gates, confirmed cleanup with grace period and duplicate merge', async t => {
  const s = await setup(t);
  const live = (await s.upload(png(80))).data.url;
  await s.patch(s.a, { photos: [live] });
  const orphan = (await s.upload(png(81))).data.url, fresh = (await s.upload(png(82))).data.url;
  s.age(orphan.slice(7));
  // Duplicates with the same bytes under different keys, as old code produced.
  const dupKey = crypto.randomUUID() + '.png', cartDupKey = crypto.randomUUID() + '.png';
  for (const key of [dupKey, cartDupKey]) {
    s.r2.objects.set(key, { bytes: png(80), httpMetadata: { contentType: 'image/png' } });
    s.db.sqlite.prepare("INSERT INTO media_objects(key,size,content_type,sha256,kind,created_at) VALUES(?,?,?,?,'upload',?)").run(key, png(80).length, 'image/png', hex(png(80)), '2030-01-01T00:00:00.000Z');
  }
  await s.patch(s.b, { photos: [`/media/${dupKey}`, live] });
  s.cartLine(`/media/${cartDupKey}`);
  assert.equal((await s.call('anon', '/api/admin/media')).status, 401);
  const view = await s.call('manager', '/api/admin/media');
  assert.equal(view.status, 200, 'managers can view with media.read');
  const item = url => view.data.items.find(i => i.url === url);
  assert.equal(item(live).live, true); assert.deepEqual(item(live).referencedBy.map(r => r.id).sort(), [s.a.id, s.b.id].sort());
  assert.equal(item(orphan).orphan, true); assert.equal(item(orphan).recent, false);
  assert.equal(item(fresh).recent, true);
  assert.equal(item(`/media/${dupKey}`).duplicateOf, cartDupKey, "the cart-referenced copy is the survivor"); assert.equal(item(`/media/${dupKey}`).mergeable, true);
  assert.equal(item(`/media/${cartDupKey}`).duplicateOf, null, 'the cart-referenced copy survives its group');
  assert.equal(item(live).duplicateOf, cartDupKey, 'a live copy can merge into the immutable survivor');
  assert.equal(view.data.summary.orphanCount, 2); assert.equal(view.data.summary.recentOrphanCount, 1);
  assert.equal((await s.call('manager', '/api/admin/media/cleanup', 'POST', { confirm: true, orphans: [orphan.slice(7)] })).status, 403, 'media.manage is owner-only by default');
  assert.equal((await s.call('manager', '/api/admin/media/scan', 'POST', {})).status, 403);
  assert.equal((await s.call('owner', '/api/admin/media/cleanup', 'POST', { orphans: [orphan.slice(7)] })).status, 400, 'confirm required');
  assert.equal((await s.call('owner', '/api/admin/media/cleanup', 'POST', { confirm: true, orphans: ['../x'] })).status, 400);
  const result = await s.call('owner', '/api/admin/media/cleanup', 'POST', { confirm: true, orphans: [orphan.slice(7), fresh.slice(7), live.slice(7)], duplicates: [dupKey, cartDupKey] });
  assert.equal(result.status, 200);
  assert.deepEqual(result.data.deleted, [orphan.slice(7)]);
  assert.deepEqual(result.data.merged, [{ key: dupKey, into: cartDupKey, products: 1 }]);
  const reasons = Object.fromEntries(result.data.skipped.map(x => [x.key, x.reason]));
  assert.equal(reasons[fresh.slice(7)], 'recent'); assert.equal(reasons[live.slice(7)], 'referenced'); assert.equal(reasons[cartDupKey], 'not-duplicate');
  assert.ok(!s.exists(orphan) && !s.r2.objects.has(dupKey) && s.exists(live) && s.exists(fresh) && s.r2.objects.has(cartDupKey));
  assert.deepEqual(JSON.parse(s.db.sqlite.prepare('SELECT overrides_json FROM products WHERE id=?').get(s.b.id).overrides_json).photos, [`/media/${cartDupKey}`, live], 'references repointed before deletion');
  assert.ok(result.data.freedBytes > 0);
  assert.equal(s.db.sqlite.prepare("SELECT COUNT(*) AS n FROM audit_events WHERE action='media.cleanup'").get().n, 1);
});

test('duplicates that lineage or a supplier source references are not merged', async t => {
  const s = await setup(t);
  const cut = (await s.cutout(s.a, s.supplierPhoto, png(90))).data;
  await s.patch(s.a, { photos: [cut.url] });
  const copy = crypto.randomUUID() + '.jpg';
  s.r2.objects.set(copy, { bytes: jpg(1), httpMetadata: { contentType: 'image/jpeg' } });
  s.db.sqlite.prepare("INSERT INTO media_objects(key,size,content_type,sha256,kind,created_at) VALUES(?,?,?,?,'unknown',?)").run(copy, 5, 'image/jpeg', hex(jpg(1)), OLD);
  s.db.sqlite.prepare('UPDATE products SET source_json=? WHERE id=?').run(JSON.stringify(source('two', [`/media/${copy}`])), s.b.id);
  const view = (await s.call('owner', '/api/admin/media')).data, item = key => view.items.find(i => i.key === key);
  assert.equal(item(copy).duplicateOf, cut.originalUrl.slice(7), 'the lineage-referenced original survives');
  assert.equal(item(copy).mergeable, false); assert.equal(item(copy).reason, 'supplier-source');
  const result = (await s.call('owner', '/api/admin/media/cleanup', 'POST', { confirm: true, duplicates: [copy, cut.originalUrl.slice(7)] })).data;
  assert.deepEqual(result.merged, []);
  assert.ok(s.r2.objects.has(copy) && s.exists(cut.originalUrl));
});

test('scan tracks existing objects with size, hash and R2 lineage, paged and resumable, never deleting', async t => {
  const s = await setup(t);
  const keys = Array.from({ length: 23 }, () => crypto.randomUUID() + '.png');
  keys.forEach((key, i) => s.r2.objects.set(key, { bytes: png(i), httpMetadata: { contentType: 'image/png' }, uploaded: new Date(OLD), customMetadata: i === 0 ? { productId: s.a.id, originalUrl: `/media/${keys[1]}`, sourceUrl: 'x' } : undefined }));
  s.r2.objects.set('not-a-media-key.txt', { bytes: new Uint8Array([1]) });
  const before = s.r2.objects.size;
  const first = (await s.call('owner', '/api/admin/media/scan', 'POST', {})).data;
  assert.equal(first.done, false); assert.equal(first.scanned, 20); assert.ok(first.cursor);
  assert.equal((await s.call('owner', '/api/admin/media', 'GET')).data.lastScanAt, null);
  const second = (await s.call('owner', '/api/admin/media/scan', 'POST', { cursor: first.cursor })).data;
  assert.equal(second.done, true); assert.equal(first.added + second.added, 23);
  assert.equal(s.r2.objects.size, before);
  const row = s.tracked(keys[0]);
  assert.deepEqual([row.kind, row.product_id, row.original_key, row.sha256, row.size, row.created_at], ['cutout', s.a.id, keys[1], hex(png(0)), png(0).length, OLD]);
  const view = (await s.call('owner', '/api/admin/media')).data;
  assert.ok(view.lastScanAt);
  assert.equal(view.items.find(i => i.key === keys[1]).orphan, true, 'lineage of an orphan does not keep it alive');
  // Cleanup deletes the orphan cutout and its orphan original in one confirmed request.
  const result = (await s.call('owner', '/api/admin/media/cleanup', 'POST', { confirm: true, orphans: [keys[1], keys[0]] })).data;
  assert.deepEqual(result.deleted.sort(), [keys[0], keys[1]].sort());
  assert.equal((await s.call('owner', '/api/admin/media/scan', 'POST', { cursor: 5 })).status, 400);
});

test('review: purge with a stale Trash row after a concurrent restore changes nothing and returns 409', async t => {
  const s = await setup(t);
  const own = (await s.upload(png(100))).data.url;
  await s.patch(s.a, { photos: [own] });
  s.db.sqlite.prepare("INSERT INTO slug_redirects(slug,product_id) VALUES('old-slug',?)").run(s.a.id);
  assert.equal((await s.call('owner', `/api/admin/products/${s.a.id}`, 'DELETE', { confirm: true })).status, 200);
  const stale = s.db.sqlite.prepare('SELECT * FROM products WHERE id=?').get(s.a.id);
  assert.equal((await s.call('owner', `/api/admin/products/${s.a.id}/restore`, 'POST', {})).status, 200);
  await assert.rejects(purgeProduct({ DB: s.db, MEDIA: s.r2, PRINCIPAL: { actor: 'owner@example.com', role: 'owner', type: 'access' } }, stale), error => error.status === 409);
  assert.equal(s.db.sqlite.prepare('SELECT COUNT(*) AS n FROM products WHERE id=?').get(s.a.id).n, 1);
  assert.equal(s.db.sqlite.prepare('SELECT COUNT(*) AS n FROM product_tombstones').get().n, 0, 'no tombstone for a live product');
  assert.equal(s.db.sqlite.prepare('SELECT COUNT(*) AS n FROM slug_redirects WHERE product_id=?').get(s.a.id).n, 1);
  assert.equal(s.db.sqlite.prepare("SELECT COUNT(*) AS n FROM audit_events WHERE action='product.purge'").get().n, 0);
  assert.ok(s.exists(own));
  // A stray tombstone can never freeze a live product's source updates.
  s.db.sqlite.prepare("INSERT INTO product_tombstones VALUES(?,?,?,?)").run(s.supplier.id, 'one', 'x', OLD);
  assert.equal((await s.call('owner', `/api/admin/suppliers/${s.supplier.id}/import`, 'POST', { items: [{ ...source('one'), title: 'Renamed source' }] })).status, 200);
  assert.equal(JSON.parse(s.db.sqlite.prepare('SELECT source_json FROM products WHERE id=?').get(s.a.id).source_json).title, 'Renamed source');
});

test('review: an object reused by dedup is not deleted automatically within the grace period', async t => {
  const s = await setup(t);
  const { url } = (await s.upload(png(110))).data;
  s.age(url.slice(7));
  await s.patch(s.a, { photos: [url] });
  assert.equal((await s.upload(png(110))).data.url, url, 'reuse touches the object');
  await s.patch(s.a, { photos: [] });
  assert.ok(s.exists(url), 'a concurrent writer may be about to reference the reused object');
  s.age(url.slice(7)); await s.patch(s.a, { photos: [url] }); await s.patch(s.a, { photos: [] });
  assert.ok(!s.exists(url), 'deleted once the grace period has passed');
});

test('review: a duplicate whose survivor disappeared is not merged; 304 only for cache validators', async t => {
  const s = await setup(t);
  const live = (await s.upload(png(120))).data.url;
  await s.patch(s.b, { photos: [live] });
  const copy = crypto.randomUUID() + '.png';
  s.r2.objects.set(copy, { bytes: png(120), httpMetadata: { contentType: 'image/png' } });
  s.db.sqlite.prepare("INSERT INTO media_objects(key,size,content_type,sha256,kind,created_at) VALUES(?,?,?,?,'upload',?)").run(copy, 9, 'image/png', hex(png(120)), '2030-01-01T00:00:00.000Z');
  await s.patch(s.a, { photos: [`/media/${copy}`] });
  // The survivor's row vanishes between the listing and the repoint (simulated by a trigger on the repoint UPDATE).
  const batch = s.db.batch;
  s.db.batch = async statements => { if (statements[0]?.sql.includes('AND EXISTS (SELECT 1 FROM media_objects')) s.db.sqlite.prepare('DELETE FROM media_objects WHERE key=?').run(live.slice(7)); return batch(statements); };
  const result = (await s.call('owner', '/api/admin/media/cleanup', 'POST', { confirm: true, duplicates: [copy] })).data;
  assert.deepEqual(result.merged, []); assert.equal(result.skipped[0].reason, 'missing');
  assert.deepEqual(JSON.parse(s.db.sqlite.prepare('SELECT overrides_json FROM products WHERE id=?').get(s.a.id).overrides_json).photos, [`/media/${copy}`]);
  assert.ok(s.r2.objects.has(copy));
  s.db.batch = batch;
  await s.patch(s.b, { published: true });
  const ok = await s.publicGet(live, { 'If-Match': '"nope"' });
  assert.equal(ok.status, 200, 'If-Match is not forwarded as a cache validator');
});
